def backfill_payments(apps, schema_editor):
    """Every invoice already marked paid gets one payment for its total, on the day it was paid."""
    from django.utils import timezone as tz
    Invoice = apps.get_model("crm", "Invoice")
    Payment = apps.get_model("crm", "Payment")
    rows = []
    for inv in Invoice.objects.filter(status="paid").prefetch_related("items"):
        total = sum(((i.quantity * i.unit_price).quantize(Decimal("0.01")) for i in inv.items.all()), Decimal("0.00"))
        if total <= 0:
            continue
        paid_on = tz.localdate(inv.paid_at) if inv.paid_at else inv.issue_date
        rows.append(Payment(invoice=inv, amount=total, paid_on=paid_on, method="other"))
    Payment.objects.bulk_create(rows)


